import 'package:flutter/material.dart';class Feature extends StatelessWidget{final IconData icon;final String title,sub,route;const Feature({super.key,required this.icon,required this.title,required this.sub,required this.route});@override Widget build(BuildContext c)=>Card(child:ListTile(leading:CircleAvatar(child:Icon(icon)),title:Text(title,style:const TextStyle(fontWeight:FontWeight.w600)),subtitle:Text(sub),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.pushNamed(c,route)));}
